@js:
(async () => {
  const nodes = await xpath(result, "//dl/dd");
  const roads = [];
  for (let i = 0; i < nodes.length; i++) {
    const node = nodes[i];
    const flags = await xpath(node, "./@flag");
    const texts = await xpath(node, "./text()");
    const flag = (flags && flags[0]) || ("线路" + (i + 1));
    const text = Array.isArray(texts) ? texts.join("") : String(texts || "");
    const episodes = String(text)
      .split("#")
      .filter(Boolean)
      .map((part) => {
        const idx = part.indexOf("$");
        if (idx < 0) {
          return { name: part, url: part };
        }
        const name = part.slice(0, idx) || part.slice(idx + 1);
        const url = part.slice(idx + 1);
        return { name, url };
      })
      .filter((ep) => ep.url);
    if (episodes.length) {
      roads.push({ name: flag, episodes });
    }
  }
  return roads;
})()

