@js:
(() => {
  const data = typeof result === "string" ? JSON.parse(result) : result;
  const item = (data && data.list && data.list[0]) || data || {};
  const from = String(item.vod_play_from || "").split("$$$");
  const urls = String(item.vod_play_url || "").split("$$$");
  const count = Math.max(from.length, urls.length);
  const roads = [];
  for (let i = 0; i < count; i++) {
    const episodes = String(urls[i] || "")
      .split("#")
      .filter(Boolean)
      .map((part) => {
        const idx = part.indexOf("$");
        if (idx < 0) {
          return { name: part, url: part };
        }
        const name = part.slice(0, idx) || part.slice(idx + 1);
        const url = part.slice(idx + 1);
        return { name, url };
      })
      .filter((ep) => ep.url);
    if (!episodes.length) {
      continue;
    }
    roads.push({
      name: from[i] || ("线路" + (i + 1)),
      episodes
    });
  }
  return roads;
})()

